?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Denúncias</title><link rel="stylesheet" href="style.css"></head><body><div class="layout"><aside class="side"><div class="brand">BRASIL <b>TERRA MÍSTICA</b></div><nav class="nav"><a href="dashboard.php">👤 Minha Conta</a><a href="insta.php">📸 BTM Insta</a><a class="active" href="denuncias.php">🚨 Denunciar Jogador</a><a href="musicas.php">🎵 Música</a><a href="servidor.php">🌐 Servidor</a><a href="logout.php">↪ Sair</a></nav></aside><main class="main"><h1>Denunciar Jogador</h1><p class="user">Envie texto e uma prova de até 25 MB.</p><?php if($flash):?><div class="alert"><?=e($flash)?></div><?php endif;?><div class="panel"><form method="post" action="denunciar.php" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Jogador denunciado</label><input class="input" name="denunciado" maxlength="32" required><label>Motivo</label><input class="input" name="motivo" maxlength="120" required><label>Descrição</label><textarea class="textarea" name="descricao" maxlength="3000" required></textarea><label>Prova — foto ou vídeo</label><input class="input" type="file" name="prova" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm,video/quicktime"><button class="btn">ENVIAR DENÚNCIA</button></form></div><h2>Minhas denúncias</h2><?php foreach($rows as $r):?><div class="panel"><div class="post-head"><b>#<?=e($r['id'])?> — <?=e($r['denunciado'])?></b><span class="status"><?=e($r['status'])?></span></div><p><b><?=e($r['motivo'])?></b></p><p><?=nl2br(e($r['descricao']))?></p><?php if($r['prova']):?><a class="btn" target="_blank" href="<?=e($r['prova'])?>">Ver prova</a><?php endif;?><?php if($r['resposta']):?><p class="notice"><b>Resposta:</b> <?=nl2br(e($r['resposta']))?></p><?php endif;?></div><?php endforeach;?></main></div></body></html>